using System;
using UnityEngine;

namespace MoonProject.Gameplay
{
    /// <summary>
    /// The SoftGlow materials gameplay effects draw with, generated by the Gameplay/Materials builder
    /// (Generated/Gameplay/Materials). Runtime code only reads it.
    /// </summary>
    public sealed class GameplayVisuals : ScriptableObject
    {
        [Tooltip("Expanding sonar ring on the ground (TechGlow, additive).")]
        [SerializeField] private Material _sonarRing;

        [Tooltip("Ground ring at an answered relic site (TechGlow, additive).")]
        [SerializeField] private Material _siteRing;

        [Tooltip("Light pillar over an answered site, seen from afar (TechGlow, additive, rising bands).")]
        [SerializeField] private Material _sitePillar;

        [Tooltip("Tractor beam cone from 07's eye (TechGlow, additive, flowing bands).")]
        [SerializeField] private Material _tractorBeam;

        [Tooltip("Tether line (TechGlow, additive, flowing bands).")]
        [SerializeField] private Material _tetherBeam;

        [Tooltip("Pickup flash where salvage folds into 07 (TechGlow, additive, fresnel ball).")]
        [SerializeField] private Material _flash;

        [Tooltip("Relic highlight halo (TechGlow, additive, inverted hull with fresnel).")]
        [SerializeField] private Material _relicHalo;

        [Tooltip("Swirling dust around an excavation (dust lavender, soft premultiplied sprites).")]
        [SerializeField] private Material _dust;

        [Tooltip("Warm ground rings: tower pad, shelf slot hint, signal bloom (WarmLamp, additive).")]
        [SerializeField] private Material _warmRing;

        [Tooltip("Warm glow ball: radio tower beacon (WarmLamp, additive, fresnel).")]
        [SerializeField] private Material _warmGlow;

        [Tooltip("Camera-facing glints over loose salvage along a debris trail (Glint shader, TechGlow).")]
        [SerializeField] private Material _salvageGlint;

        [Tooltip("Camera-facing glints over a friend's missing parts (Glint shader, WarmLamp amber).")]
        [SerializeField] private Material _partGlint;

        [Tooltip("Light pillar over a broken friend that answered (WarmLamp, additive, rising bands).")]
        [SerializeField] private Material _friendPillar;

        [Tooltip("The Rover Bay's weld sparks (WarmLamp, additive, soft round sprites).")]
        [SerializeField] private Material _spark;

        [Tooltip("The soft amber halo over home seen from across the basin (WarmLamp, additive, round sprite).")]
        [SerializeField] private Material _homeHalo;

        [Tooltip("The pulse running along the ground from a newly lit relay mast toward home (WarmLamp, additive).")]
        [SerializeField] private Material _linkPulse;

        [Tooltip("Art's station pads (Generated/Art/Base/StationPad_<cm>), one per size.")]
        [SerializeField] private GameObject[] _pads = Array.Empty<GameObject>();

        [Tooltip("Each pad's radius in metres (Art's PadRadii), matching the pads above.")]
        [SerializeField] private float[] _padRadii = Array.Empty<float>();

        [Tooltip("Art's tower components (Generated/Art/Pickups/Part_*), each named as the part's id.")]
        [SerializeField] private GameObject[] _components = Array.Empty<GameObject>();

        [Tooltip("Art's blueprint tube (Generated/Art/Pickups/BlueprintTube.prefab): a tube waiting on the ground at " +
                 "a world anchor (docs/features/M3-21).")]
        [SerializeField] private GameObject _tube;

        [Tooltip("Art's old tape deck (Generated/Art/Rover/Kit_TapeDeck.prefab): Tilly's glint on the ground (M3-24).")]
        [SerializeField] private GameObject _tapeDeck;

        public Material SonarRing => _sonarRing;
        public Material SiteRing => _siteRing;
        public Material SitePillar => _sitePillar;
        public Material TractorBeam => _tractorBeam;
        public Material TetherBeam => _tetherBeam;
        public Material Flash => _flash;
        public Material RelicHalo => _relicHalo;
        public Material Dust => _dust;
        public Material WarmRing => _warmRing;
        public Material WarmGlow => _warmGlow;
        public Material SalvageGlint => _salvageGlint;
        public Material PartGlint => _partGlint;
        public Material FriendPillar => _friendPillar;
        public Material Spark => _spark;
        public Material HomeHalo => _homeHalo;
        public Material LinkPulse => _linkPulse;
        public GameObject Tube => _tube;
        public GameObject TapeDeck => _tapeDeck;

        /// <summary>Art's station pad (StationPad_&lt;cm&gt;) whose radius is nearest <paramref name="radius"/>.</summary>
        public GameObject PadFor(float radius)
        {
            int best = 0;
            for (int i = 1; i < _pads.Length; i++)
            {
                best = Mathf.Abs(_padRadii[i] - radius) < Mathf.Abs(_padRadii[best] - radius) ? i : best;
            }

            return _pads[best];
        }

        /// <summary>Art's model of the tower component <paramref name="partId"/> (its prefab name), or null.</summary>
        public GameObject ComponentModel(string partId)
        {
            for (int i = 0; i < _components.Length; i++)
            {
                if (_components[i] != null && _components[i].name == partId)
                {
                    return _components[i];
                }
            }

            return null;
        }

        /// <summary>Null when every material is assigned, else the first missing one.</summary>
        public string Validate()
        {
            return _sonarRing == null ? "sonar ring material is missing"
                : _siteRing == null ? "site ring material is missing"
                : _sitePillar == null ? "site pillar material is missing"
                : _tractorBeam == null ? "tractor beam material is missing"
                : _tetherBeam == null ? "tether beam material is missing"
                : _flash == null ? "flash material is missing"
                : _relicHalo == null ? "relic halo material is missing"
                : _dust == null ? "dust material is missing"
                : _warmRing == null ? "warm ring material is missing"
                : _warmGlow == null ? "warm glow material is missing"
                : _salvageGlint == null ? "salvage glint material is missing"
                : _partGlint == null ? "part glint material is missing"
                : _friendPillar == null ? "friend pillar material is missing"
                : _spark == null ? "spark material is missing"
                : _homeHalo == null ? "home halo material is missing"
                : _linkPulse == null ? "link pulse material is missing"
                : _pads == null || _pads.Length == 0 || _padRadii == null || _padRadii.Length != _pads.Length ||
                  Array.IndexOf(_pads, null) >= 0 ? "Art's station pads are missing (run Gameplay/Materials)"
                : _components == null || Array.IndexOf(_components, null) >= 0
                    ? "Art's tower components are missing (run Gameplay/Materials)"
                : _tube == null ? "Art's blueprint tube is missing (run Gameplay/Materials)"
                : _tapeDeck == null ? "Art's tape deck is missing (run Gameplay/Materials)"
                : null;
        }

        internal void PopulatePads(GameObject[] pads, float[] radii)
        {
            _pads = pads;
            _padRadii = radii;
        }

        internal void PopulateComponents(GameObject[] parts)
        {
            _components = parts;
        }

        internal void PopulateTube(GameObject tube)
        {
            _tube = tube;
        }

        internal void PopulateTapeDeck(GameObject deck)
        {
            _tapeDeck = deck;
        }

        internal void Populate(Material sonarRing, Material siteRing, Material sitePillar, Material tractorBeam,
            Material tetherBeam, Material flash, Material relicHalo, Material dust, Material warmRing,
            Material warmGlow, Material salvageGlint, Material partGlint, Material friendPillar, Material spark,
            Material homeHalo, Material linkPulse)
        {
            _sonarRing = sonarRing;
            _siteRing = siteRing;
            _sitePillar = sitePillar;
            _tractorBeam = tractorBeam;
            _tetherBeam = tetherBeam;
            _flash = flash;
            _relicHalo = relicHalo;
            _dust = dust;
            _warmRing = warmRing;
            _warmGlow = warmGlow;
            _salvageGlint = salvageGlint;
            _partGlint = partGlint;
            _friendPillar = friendPillar;
            _spark = spark;
            _homeHalo = homeHalo;
            _linkPulse = linkPulse;
        }
    }
}
